            "Children should have the freedom to make choices, test ideas, and learn from the results. Rather than expecting every child to follow the same path, schools can create flexible learning environments that recognise different interests and abilities. Creativity develops through experience, practice, encouragement, and opportunities to explore. It should be nurtured throughout childhood and beyond."
